using Bird.Core;

var failures = 0; var count = 0;
void Test(string name, Action action) { if(args.Contains("--extensions") && !name.StartsWith("extension"))return; count++; try { action(); Console.WriteLine("PASS " + name); } catch(Exception e) { failures++; Console.WriteLine("FAIL " + name + ": " + e.Message); } }
void Check(bool value, string message) { if (!value) throw new Exception(message); }
BirdCatalog Catalog() => BirdCatalog.Load(Path.GetFullPath("huashu-bird-sticker"));
Test("real catalogue and four initial species", () => { var c = Catalog(); var e = new ProgressEngine(c, new SaveData(), new Random(1)); Check(c.Birds.Count == 11011, "species count"); Check(e.Data.Unlocks.Select(x=>x.Id).SequenceEqual(ProgressEngine.InitialIds), "four ordered initial species"); Check(e.UnlockedBirds.All(b=>b.HasSticker), "initial sticker existence"); });
Test("599/600 second boundary and remainder", () => { var e = new ProgressEngine(Catalog(), new SaveData()); e.Advance(599); Check(e.Data.Chests==0,"early chest"); e.Advance(1); Check(e.Data.Chests==1 && e.Data.Seconds==0,"boundary chest"); e.Advance(1205); Check(e.Data.Chests==3 && e.Data.Seconds==5,"multiple intervals"); });
Test("negative and invalid elapsed ignored", () => { var e = new ProgressEngine(Catalog(), new SaveData()); e.Advance(-10); e.Advance(double.NaN); e.Advance(double.PositiveInfinity); Check(e.Data.Seconds==0 && e.Data.Chests==0,"invalid time"); });
Test("all three tiers award 5/2/1 distinct birds", () => { foreach(var pair in new[]{(0.0,5,Rarity.Common),(0.71,2,Rarity.Rare),(0.99,1,Rarity.Ultra)}) { var e = new ProgressEngine(Catalog(), new SaveData(), new FixedRandom(pair.Item1)); e.Advance(600); var r=e.OpenChest(); Check(r.Count==pair.Item2,"tier reward count"); Check(r.All(b=>b.Rarity==pair.Item3),"tier selection"); Check(r.Select(b=>b.Id).Distinct().Count()==r.Count,"duplicate"); Check(e.Data.Chests==0,"chest consumption"); } });
Test("late pool exhaustion and no duplicate rewards", () => { var c=Catalog(); var e=new ProgressEngine(c,new SaveData(),new Random(42)); var remaining=c.Birds.Where(b=>b.Collectible && !ProgressEngine.InitialIds.Contains(b.Id)).TakeLast(3).ToList(); e.UnlockAll(); e.Data.Unlocks.RemoveAll(x=>remaining.Any(b=>b.Id==x.Id)); e.Restore(e.Data); e.Data.Chests=3; var found=new List<string>(); while(!e.Complete) found.AddRange(e.OpenChest().Select(b=>b.Id)); Check(found.Count==3 && found.Distinct().Count()==3,"remaining rewards"); var boxes=e.Data.Chests; Check(e.OpenChest().Count==0 && e.Data.Chests==boxes,"empty pool consumed chest"); e.Advance(1800); Check(e.Data.Chests==boxes,"complete still generating"); });
Test("reset restores four and clears rewards but keeps settings", () => { var e=new ProgressEngine(Catalog(),new SaveData()); e.Data.Dark=true; e.Data.Topmost=false; e.UnlockAll(); e.Data.Chests=5; e.Data.Seconds=50; e.Reset(); Check(e.Data.Unlocks.Count==4 && e.Data.Chests==0 && e.Data.Seconds==0,"reset progress"); Check(e.Data.Dark && !e.Data.Topmost,"reset preferences"); Check(!e.Complete,"reset complete flag"); });
Test("locked species cannot become current pet", () => { var e=new ProgressEngine(Catalog(),new SaveData()); var before=e.Data.CurrentId; e.Select(e.Catalog.Birds.First(b=>!e.Data.Unlocks.Any(u=>u.Id==b.Id)).Id); Check(e.Data.CurrentId==before,"locked selected"); e.Select(ProgressEngine.InitialIds[1]); Check(e.Data.CurrentId==ProgressEngine.InitialIds[1],"unlocked not selected"); });
Test("save round trip and corrupt primary fallback", () => { var dir=Path.GetFullPath(Path.Combine("tests",".runs","bird-tests-"+Guid.NewGuid())); Directory.CreateDirectory(dir); try { var s=new ProgressStore(Path.Combine(dir,"save.json")); var d=new SaveData{Chests=3,Seconds=17,Dark=true}; s.Save(d); d.Chests=4; s.Save(d); Check(s.Load().Chests==4,"round trip"); File.WriteAllText(s.Path,"broken"); var restored=s.Load(); Check(restored.Chests==3 && restored.Dark,"backup fallback"); Check(Directory.GetFiles(dir,"*.corrupt-*").Length==1,"corrupt evidence not preserved"); } finally { Directory.Delete(dir,true); } });
Test("structurally corrupt save uses valid backup", () => { var dir=Path.GetFullPath(Path.Combine("tests",".runs","structure-"+Guid.NewGuid())); Directory.CreateDirectory(dir); try { var store=new ProgressStore(Path.Combine(dir,"save.json"));store.Save(new SaveData{Chests=7});store.Save(new SaveData{Chests=8});File.WriteAllText(store.Path,"{\"Version\":1,\"Unlocks\":[null],\"History\":[]}");Check(store.Load().Chests==7,"invalid element bypassed backup"); } finally {Directory.Delete(dir,true);} });
Test("extension favorites toggle and reject locked",()=>{dynamic e=new ProgressEngine(Catalog(),new SaveData());e.ToggleFavorite(ProgressEngine.InitialIds[0]);Check(e.Data.FavoriteIds.Contains(ProgressEngine.InitialIds[0]),"not favorited");e.ToggleFavorite(ProgressEngine.InitialIds[0]);Check(e.Data.FavoriteIds.Count==0,"not removed");e.ToggleFavorite("Phoenicurus_fuliginosus");Check(e.Data.FavoriteIds.Count==0,"locked favorited");});
Test("extension timed favorite rotation and empty pool",()=>{dynamic e=new ProgressEngine(Catalog(),new SaveData());e.Data.RotationMinutes=1.0;e.Data.FavoritesOnly=true;Check(!e.AdvanceRotation(60.0),"empty favorites rotated");e.ToggleFavorite(ProgressEngine.InitialIds[1]);Check(!e.AdvanceRotation(59.0),"early rotation");Check(e.AdvanceRotation(1.0),"boundary rotation missed");Check(e.Data.CurrentId==ProgressEngine.InitialIds[1],"wrong rotation pool");Check(!e.AdvanceRotation(600.0),"single current favorite should stay");e.Reset();Check(e.Data.FavoriteIds.Count==0,"reset favorites");});
Test("extension fullscreen default enabled legacy save",()=>{var data=System.Text.Json.JsonSerializer.Deserialize<SaveData>("{}");Check(data!.GetType().GetProperty("FullscreenDnd")?.GetValue(data) is true,"fullscreen DND not enabled by default");});
Test("extension fullscreen visibility respects manual hide and setting",()=>{var v=new FullscreenVisibility();Check(!v.ShouldShow(true,true),"fullscreen not hidden");Check(v.ShouldShow(true,false),"not restored");v.SetManualHidden(true);Check(!v.ShouldShow(false,false),"manual hidden restored");v.SetManualHidden(false);Check(v.ShouldShow(false,true),"disabled DND still hides");});
Test("extension chest early boost and threshold",()=>{var core=new ProgressEngine(Catalog(),new SaveData());dynamic e=core;Check(e.ChestIntervalSeconds==600.0,"early interval");e.Advance(599.0);Check(core.Data.Chests==0,"early award");e.Advance(1.0);Check(core.Data.Chests==1,"ten minute award");e.UnlockAll();core.Data.Unlocks=core.Data.Unlocks.Take(50).ToList();e.Restore(core.Data);Check(e.ChestIntervalSeconds==1800.0 && !e.CanCustomizeChestInterval,"50 boundary");core.Data.Unlocks.Add(new Unlock{Id=core.Catalog.Birds.First(b=>!core.Data.Unlocks.Any(u=>u.Id==b.Id)).Id,Sequence=100});e.Restore(core.Data);Check(e.CanCustomizeChestInterval,"51 customization");e.SetChestMinutes(2.0);Check(e.ChestIntervalSeconds==120.0,"custom interval");});
Console.WriteLine($"{count-failures}/{count} passed"); return failures==0?0:1;
sealed class FixedRandom(double value) : Random { public override double NextDouble()=>value; }
